22	    @Mapping(target = "salutation", expression = "java(toSalutation(owner))")
23	    @Mapping(target = "initials", expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" + Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
24	    @Mapping(target = "membershipNumber", expression = "java(toMembershipNumber(owner))")
25	    @Mapping(target = "checkDigit", expression = "java(toCheckDigit(owner))")
26	    @Mapping(target = "membershipPoints", expression = "java(toMembershipPoints(owner))")
27	    @Mapping(target = "membershipLevel", expression = "java(toMembershipLevel(owner))")
28	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
29	    @Mapping(target = "timezone", expression = "java(toTimezone(owner))")
