32	    @Mapping(target = "ageBand", expression = "java(toAgeBand(owner))")
33	    @Mapping(target = "telephoneDisplay", expression = "java(toTelephoneDisplay(owner))")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /**
37	     * Derives the owner's {@code salutation}: the {@code title} followed by a single space and the
38	     * {@code lastName} when a title is present, or just the {@code lastName} when no title was
39	     * supplied.
40	     */
41	    default String toSalutation(Owner owner) {
42	        String title = owner.getTitle();
43	        if (title == null || title.isBlank()) {
44	            return owner.getLastName();
45	        }
46	        return title + " " + owner.getLastName();
47	    }
48	
49	    /**
50	     * Derives the owner's {@code telephoneDisplay}: the stored E.164 {@code telephone} formatted
51	     * for humans (see {@link org.springframework.samples.petclinic.rest.function.owner.E164Telephone#display}).
52	     * The raw {@code telephone} is left in E.164 form.
53	     */
54	    default String toTelephoneDisplay(Owner owner) {
55	        return org.springframework.samples.petclinic.rest.function.owner.E164Telephone
56	                .display(owner.getTelephone());
57	    }
58	
59	    /**
60	     * Derives the owner's {@code ageBand} from its {@code birthDate} measured against its
61	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} from 18 to 64,
62	     * {@code SENIOR} at 65 or older. Returns null when either date is absent (so no band is
63	     * reported for owners with no supplied birth date).
64	     */
65	    default org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
66	        java.time.LocalDate birthDate = owner.getBirthDate();
67	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
68	        if (birthDate == null || registrationDate == null) {
69	            return null;
70	        }
71	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
72	        if (age < 18) {
73	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.MINOR;
74	        }
75	        if (age < 65) {
76	            return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.ADULT;
77	        }
78	        return org.springframework.samples.petclinic.rest.dto.OwnerDto.AgeBandEnum.SENIOR;
79	    }
80	
81	    /**
82	     * Derives the owner's {@code identityKey}: the single value that consolidates all
83	     * duplicate detection, {@code normalizedTelephone + '|' + (email or empty) + '|' +
84	     * (householdId or empty)}.
85	     */
86	    default String toIdentityKey(Owner owner) {
87	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner);
88	    }
89	
90	    /**
91	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
92	     * otherwise {@code PHONE}.
93	     */
94	    default String toContactPreference(Owner owner) {
95	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
96	        return hasEmail ? "EMAIL" : "PHONE";
97	    }
98	
99	    /**
100	     * Derives the owner's locality (region) from its region-and-hash identity: the
101	     * {@code customerCode} is {@code <REGION>-<HASH8>}, so the locality is the REGION segment
102	     * preceding the hash. Falls back to deriving the region directly from the postcode/city
103	     * (see {@link org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode})
104	     * only for unmigrated owners that carry no customer code.
105	     */
106	    default String toLocality(Owner owner) {
107	        String customerCode = owner.getCustomerCode();
108	        if (customerCode != null) {
109	            int dash = customerCode.indexOf('-');
110	            if (dash > 0) {
111	                return customerCode.substring(0, dash);
112	            }
113	        }
114	        return org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
115	                .region(owner.getPostcode(), owner.getCity());
116	    }
117	
118	    /** Region -> IANA timezone, the pinned region-to-timezone table. */
119	    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
120	            "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");
121	
122	    /**
123	     * Derives the owner's {@code timezone}: the IANA name for the owner's locality/region via
124	     * the fixed region-to-timezone table (NSW-&gt;Australia/Sydney, VIC-&gt;Australia/Melbourne,
125	     * QLD-&gt;Australia/Brisbane). Returns null when the region yields no known timezone (e.g.
126	     * an {@code UNKNOWN} locality).
127	     */
128	    default String toTimezone(Owner owner) {
129	        return REGION_TIMEZONE.get(toLocality(owner));
130	    }
131	
132	    /**
133	     * Derives the owner's membership points: start at 0; add 2 when an email is present; add 1
134	     * when the owner has no namesakes ({@code namesakeCount} is 0); add 2 for a household of 3 or
135	     * more ({@code householdSize} at least 3); add 3 for tenure over 365 days (a
136	     * {@code registrationDate} more than 365 days ago). A newly created owner has zero tenure.
137	     */
138	    default Integer toMembershipPoints(Owner owner) {
139	        int points = 0;
140	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
141	        if (hasEmail) {
142	            points += 2;
143	        }
144	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
145	        if (unique) {
146	            points += 1;
147	        }
148	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
149	            points += 2;
150	        }
151	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
152	        if (registrationDate != null && java.time.temporal.ChronoUnit.DAYS
153	                .between(registrationDate, java.time.LocalDate.now()) > 365) {
154	            points += 3;
155	        }
156	        return points;
157	    }
158	
159	    /**
160	     * Derives the owner's numeric membership level (1 to 4) from its {@code membershipPoints}:
161	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
162	     */
163	    default Integer toMembershipLevel(Owner owner) {
164	        int points = toMembershipPoints(owner);
165	        if (points >= 6) {
166	            return 4;
167	        }
168	        if (points >= 4) {
169	            return 3;
170	        }
171	        if (points >= 2) {
172	            return 2;
173	        }
174	        return 1;
175	    }
176	
177	    /**
178	     * Derives the owner's membership number as {@code <customerCode>-M<YY>}, where YY is the
179	     * last two digits of the registration-date year (e.g. {@code NSW-1A2B3C4D-M26}). Returns
180	     * null when either the customer code or registration date is absent (e.g. unmigrated seed
181	     * data).
182	     */
183	    default String toMembershipNumber(Owner owner) {
184	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
185	            return null;
186	        }
187	        return owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
188	    }
189	
190	    /**
191	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the
192	     * digits contained in the {@code customerCode}. Returns null when the customer code is
193	     * absent (e.g. unmigrated seed data).
194	     */
195	    default Integer toCheckDigit(Owner owner) {
196	        String customerCode = owner.getCustomerCode();
197	        if (customerCode == null) {
198	            return null;
199	        }
200	        int sum = 0;
201	        boolean dbl = true;
202	        for (int i = customerCode.length() - 1; i >= 0; i--) {
203	            char c = customerCode.charAt(i);
204	            if (c < '0' || c > '9') {
205	                continue;
206	            }
207	            int d = c - '0';
208	            if (dbl) {
209	                d *= 2;
210	                if (d > 9) {
211	                    d -= 9;
212	                }
213	            }
214	            sum += d;
215	            dbl = !dbl;
216	        }
217	        return (10 - (sum % 10)) % 10;
218	    }
219	
220	    Owner toOwner(OwnerDto ownerDto);
221	
222	    @Mapping(target = "id", ignore = true)
223	    @Mapping(target = "pets", ignore = true)
224	    @Mapping(target = "customerCode", ignore = true)
225	    @Mapping(target = "householdId", ignore = true)
226	    @Mapping(target = "namesakeCount", ignore = true)
227	    @Mapping(target = "householdSize", ignore = true)
228	    @Mapping(target = "possibleDuplicate", ignore = true)
229	    @Mapping(target = "possibleDuplicateOf", ignore = true)
230	    @Mapping(target = "deleted", ignore = true)
231	    Owner toOwner(OwnerFieldsDto ownerDto);
232	
233	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
234	
235	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
236	
237	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
238	        OwnerPageDto ownerPageDto = new OwnerPageDto();
239	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
240	        ownerPageDto.setPage(ownerPage.getNumber());
241	        ownerPageDto.setSize(ownerPage.getSize());
242	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
243	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
244	        return ownerPageDto;
245	    }
246	}
